               (("Step 3", "Étape 3"), ("Break it, then repair it", "Cassez, puis réparez"), ("16 incidents; the wrong repair fails.", "16 incidents ; la mauvaise réparation échoue."), "lcc-pannes", [3, 34, 94, 30]),
               (("Step 4", "Étape 4"), ("Hover a word", "Survolez un mot"), ("139 terms explained where you read them.", "139 termes expliqués là où vous les lisez."), "lcc-definition", [40, 28, 44, 17]),
